( LC_ALL=C; export LC_ALL; . $HOME/hadavin-smoke/env.sh; N0=$(cat $T/keys-before-s10.txt 2>/dev/null | tr -d ' \r\n'); case "$N0" in ''|*[!0-9]*) echo "GATE2 keys-before-s10.txt missing or not a number: STOP";; *) S=$(cat $T/keys.txt 2>/dev/null | tr -d '\r' | awk -v n=$N0 'NR>n&&$1=="A"{la++;if(!($2 in sa)){sa[$2]=1;ka=$2;na++}} NR>n&&$1=="B"{lb++;if(!($2 in sb)){sb[$2]=1;kb=$2;nb++}} END{printf "%d %d %d %d %s %s\n",la,na,lb,nb,(ka==""?"-":ka),(kb==""?"-":kb)}'); set -f; set -- $S; set +f; KA=$5; KB=$6; echo "GATE2 keys.txt lines before S10: $N0; after: A lines=$1 A ids=$2 B lines=$3 B ids=$4 KA=$KA KB=$KB"; if [ "$2" != 1 ] || [ "$4" != 1 ]; then echo "GATE2 not exactly one A id and one B id after the saved line count: STOP"; elif [ "$KA" = "$KB" ]; then echo "GATE2 A and B have the same key: STOP"; else case "$KA$KB" in *[!A-Za-z0-9_-]*) echo "GATE2 key has an unexpected character: STOP";; *) N=$(pgq -U smk_count -d postgres -c "SELECT count(*) FROM mf_leads WHERE lead_key IN ('$KA','$KB')" 2>$T/gate2.err | tee $T/gate2.out | head -n 1 | tr -d ' \r'); echo "GATE2 count: $N"; if [ "$N" = 2 ]; then echo "GATE2 PASS"; else echo "GATE2 FAIL: STOP"; fi;; esac; fi;; esac )
